content:
Below is a clean Terraform implementation using a reusable module.

It provisions:

- **S3 bucket** with:
  - versioning
  - server-side encryption
  - public access blocked
- **RDS PostgreSQL** with:
  - deletion protection
  - backup retention
  - not publicly accessible
- **IAM role for service accounts**
  - supports OIDC trust for Kubernetes service accounts
  - least-privilege inline policy for the S3 bucket

It also supports **dev/prod** using **`tfvars`** and can also work with **Terraform workspaces** if you prefer.

---

# Suggested structure

```text
terraform/
├── main.tf
├── variables.tf
├── outputs.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    └── app_infra/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

# Module: `modules/app_infra/variables.tf`

```hcl
variable "name" {
  description = "Base name for resources"
  type        = string
}

variable "environment" {
  description = "Environment name, e.g. dev or prod"
  type        = string
}

variable "aws_region" {
  description = "AWS region"
  type        = string
}

variable "tags" {
  description = "Common tags"
  type        = map(string)
  default     = {}
}

# S3
variable "bucket_force_destroy" {
  description = "Allow bucket deletion with objects inside"
  type        = bool
  default     = false
}

variable "bucket_kms_key_id" {
  description = "Optional KMS key ID/ARN for bucket encryption. If null, use AES256."
  type        = string
  default     = null
}

# RDS
variable "db_name" {
  description = "Initial database name"
  type        = string
}

variable "db_username" {
  description = "Database username"
  type        = string
}

variable "db_password" {
  description = "Database password"
  type        = string
  sensitive   = true
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "db_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "15.7"
}

variable "db_multi_az" {
  description = "Enable Multi-AZ for RDS"
  type        = bool
  default     = false
}

variable "db_storage_encrypted" {
  description = "Enable encryption for RDS storage"
  type        = bool
  default     = true
}

variable "db_backup_retention_period" {
  description = "RDS backup retention in days"
  type        = number
  default     = 7
}

variable "db_deletion_protection" {
  description = "Enable deletion protection"
  type        = bool
  default     = true
}

variable "db_publicly_accessible" {
  description = "Whether DB is publicly accessible"
  type        = bool
  default     = false
}

variable "db_subnet_ids" {
  description = "Private subnet IDs for RDS subnet group"
  type        = list(string)
}

variable "vpc_security_group_ids" {
  description = "Security groups for RDS"
  type        = list(string)
}

variable "skip_final_snapshot" {
  description = "Skip final snapshot on deletion"
  type        = bool
  default     = false
}

# IAM / IRSA
variable "oidc_provider_arn" {
  description = "OIDC provider ARN for EKS IRSA"
  type        = string
}

variable "oidc_provider_url" {
  description = "OIDC provider URL without https:// for trust condition, e.g. oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"
  type        = string
}

variable "kubernetes_namespace" {
  description = "Kubernetes namespace for the service account"
  type        = string
}

variable "kubernetes_service_account_name" {
  description = "Kubernetes service account name"
  type        = string
}
```

