# Module: `modules/app_infra/main.tf`

```hcl
resource "aws_s3_bucket" "assets" {
  bucket        = "${var.name}-${var.environment}-assets"
  force_destroy = var.bucket_force_destroy

  tags = merge(var.tags, {
    Name        = "${var.name}-${var.environment}-assets"
    Environment = var.environment
  })
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.bucket_kms_key_id != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.bucket_kms_key_id
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "deny_insecure_transport" {
  bucket = aws_s3_bucket.assets.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.assets.arn,
          "${aws_s3_bucket.assets.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_db_subnet_group" "this" {
  name       = "${var.name}-${var.environment}-db-subnets"
  subnet_ids = var.db_subnet_ids

  tags = merge(var.tags, {
    Name        = "${var.name}-${var.environment}-db-subnets"
    Environment = var.environment
  })
}

resource "aws_db_instance" "postgres" {
  identifier                     = "${var.name}-${var.environment}-postgres"
  engine                         = "postgres"
  engine_version                 = var.db_engine_version
  instance_class                 = var.db_instance_class
  allocated_storage              = var.db_allocated_storage
  db_name                        = var.db_name
  username                       = var.db_username
  password                       = var.db_password
  db_subnet_group_name           = aws_db_subnet_group.this.name
  vpc_security_group_ids         = var.vpc_security_group_ids
  publicly_accessible            = var.db_publicly_accessible
  multi_az                       = var.db_multi_az
  storage_encrypted              = var.db_storage_encrypted
  backup_retention_period        = var.db_backup_retention_period
  deletion_protection            = var.db_deletion_protection
  skip_final_snapshot            = var.skip_final_snapshot
  auto_minor_version_upgrade     = true
  apply_immediately              = false
  performance_insights_enabled   = false
  deletion_protection            = var.db_deletion_protection

  tags = merge(var.tags, {
    Name        = "${var.name}-${var.environment}-postgres"
    Environment = var.environment
  })
}

data "aws_iam_policy_document" "irsa_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values = [
        "system:serviceaccount:${var.kubernetes_namespace}:${var.kubernetes_service_account_name}"
      ]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "service_account" {
  name               = "${var.name}-${var.environment}-sa-role"
  assume_role_policy = data.aws_iam_policy_document.irsa_assume_role.json

  tags = merge(var.tags, {
    Name        = "${var.name}-${var.environment}-sa-role"
    Environment = var.environment
  })
}

data "aws_iam_policy_document" "service_account_s3_access" {
  statement {
    sid    = "ListBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.assets.arn
    ]
  }

  statement {
    sid    = "ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = [
      "${aws_s3_bucket.assets.arn}/*"
    ]
  }
}

resource "aws_iam_role_policy" "service_account_s3_access" {
  name   = "${var.name}-${var.environment}-s3-access"
  role   = aws_iam_role.service_account.id
  policy = data.aws_iam_policy_document.service_account_s3_access.json
}
```

